package com.corp.wiki.controller;

import com.corp.wiki.dto.TagUpdateDto;
import com.corp.wiki.service.ArticleService;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/kb/articles")
public class ArticleTagController {

    private final ArticleService articleService;

    public ArticleTagController(ArticleService articleService) {
        this.articleService = articleService;
    }

    @PutMapping("/{articleId}/tags")
    @PreAuthorize("@articleSecurityService.canEditArticle(#articleId, authentication.name)")
    public ResponseEntity<String> updateArticleTags(
            @PathVariable Long articleId,
            @RequestBody TagUpdateDto tagDto) {
        articleService.setTags(articleId, tagDto.getTags());
        return ResponseEntity.ok("Tags updated");
    }
}
